#include <map>
#include <list>
#include <vector>

using namespace std;

#define assert(condition) ((void)0)

typedef int control_id_t;
typedef int device_id_t;
typedef int axis_id_t;

class singleton
{
};

class input_device;
class rumble_manager;

typedef vector<input_device *> device_map_t;

class device_axis
{
public:
    device_axis()
    {}

    device_axis(device_id_t dev, axis_id_t axis)
        : device(dev),
          axis(axis)
    {}

private:
    device_id_t device;
    axis_id_t axis;
    int control_axis;

    friend class input_mgr;
};

typedef list<device_axis> device_axis_list_t;

enum control_t
{
    CT_BOOLEAN,
    CT_RATIONAL,
};

class game_control
{
public:
    game_control()
    {}

    game_control(control_id_t _name, control_t _type)
        : name(_name),
          type(_type)
    {}

private:
    control_id_t name;
    control_t type;
    device_axis_list_t mapping;

    friend class input_mgr;
};

typedef map<control_id_t, game_control> control_map_t;

class input_mgr : public singleton
{
public:
    void register_control(const game_control &control);

private:
    rumble_manager *rumble_ptr;
    device_map_t device_map;
    control_map_t control_map;
};

void input_mgr::register_control(const game_control &control)
{
    assert(control_map.find(control.name) == control_map.end());
    control_map[control.name] = control;
}
